update pages set contenu = '{"gabarit":"fiche","chapeau":"La Française des Jeux exploite un site industriel proche de Paris. Les lignes de production y tournent sous forte activité.\nPour garantir la fiabilité de ses équipements, la FDJ a renforcé ses équipes de maintenance avec un technicien Migen affecté en continu. La mission couvre 2025 et 2026.","fiche":[],"contexte":"**Une équipe de maintenance en forte activité ne tombe pas d''un coup.** Elle recule poste après poste, jusqu''à ce que le préventif disparaisse du planning.\nLa FDJ a posé trois objectifs, sans ambiguïté.\n**Renforcer l''équipe de maintenance interne**, sans la remplacer.\n**Assurer la disponibilité des équipements industriels**, en continu.\n**Réduire les temps d''arrêt** et les délais d''intervention.\nLe point commun des trois : ils demandent une présence permanente, pas un dépannage appelé quand la ligne est déjà à l''arrêt.\nUn prestataire qui envoie une personne différente à chaque visite ne réduit aucun délai. Le temps gagné sur le déplacement se reperd sur le diagnostic.\nC''est la raison du choix d''un intervenant unique, affecté au site dans la durée, qui finit par connaître les installations mieux que la documentation.","intervention":"**Vous récupérez le préventif, pas seulement les urgences.** Le technicien Migen tient la maintenance préventive et curative des lignes de production.\n**Vous gagnez du temps sur le diagnostic.** Les pannes sont identifiées sur place, par quelqu''un qui connaît déjà les installations.\n**Vos équipes sont appuyées, pas remplacées.** L''intervenant vient en soutien dans un contexte de forte activité.\n**Vous démarrez sans formation initiale longue.** Le technicien retenu a l''expérience des environnements industriels exigeants.\n**Vous avez un interlocuteur côté Migen.** Un référent technique assure le suivi et la coordination pendant toute la mission.","resultats":[]}'::jsonb where path = '/preuves/fdj/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Site","valeur":"Française des Jeux, site industriel proche de Paris"},{"libelle":"Périmètre","valeur":"Lignes de production, préventif et curatif"},{"libelle":"Effectif Migen","valeur":"1 technicien de maintenance expérimenté"},{"libelle":"Présence","valeur":"Continue, intégré aux équipes FDJ"},{"libelle":"Suivi","valeur":"Référent technique Migen"},{"libelle":"Depuis quand","valeur":"2025 et 2026"}]'::jsonb) where path = '/preuves/fdj/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"L''intégration dans la structure existante","libelle":"s''est faite efficacement."},{"valeur":"L''expertise a été immédiate","libelle":"pour les équipes en place."},{"valeur":"La continuité de service","libelle":"a été tenue, sans rupture dans les interventions."}]'::jsonb) where path = '/preuves/fdj/';
